def main() -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    for d in DEFS:
        rec = {**d, "mode": "new-document-from-text", "section_id": "key-facts", "section_title": "עיקרי ההוראה", "draft_note": NOTE,
               "ingest_note": "קליטה מטקסט ה-OCR של keep_pages בלבד (ingestion.text_ingest.document_from_def עם ocr_txt); הבלוק מוחל אחרי הקליטה"}
        (OUT / f"{d['document_id']}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1) + "\n", encoding="utf-8", newline="\n")
    print(f"[wave8] {len(DEFS)} FOI definitions -> {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
